<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientTosUriAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientTosUriAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientTosUriAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getTosUri returns null on a freshly created holder.
     */
    public function testTosUriNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientTosUriAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isTosUriAssigned());
        $this->assertNull($holder->getTosUri());
    }
}
class ImplWithTrustedClientTosUriAttributeHolderUnitTest
{
    use TrustedClientTosUriAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedTosUriRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultTosUri();
    }
}
